package vip.xiaonuo.srm.exchange;

import java.util.*;
import java.time.Duration;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import jakarta.validation.Validator;
import jakarta.validation.constraints.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;
import org.springframework.scheduling.annotation.Scheduled;
import vip.xiaonuo.common.exception.CommonException;
import vip.xiaonuo.srm.collaboration.api.SrmCollaborationIngressApi;
import vip.xiaonuo.srm.collaboration.api.SrmCollaborationIngressApi.*;
import static vip.xiaonuo.srm.exchange.ExchangeStore.*;

@Component @RequiredArgsConstructor
public class ExchangeEngine {
 private final vip.xiaonuo.srm.performance.api.SrmQualityIngressApi quality;private final ExchangeStore x; private final SrmCollaborationIngressApi business; private final Validator validator;
 private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).followRedirects(HttpClient.Redirect.NEVER).build();
 public record Ingress(@NotBlank @Pattern(regexp="[A-Za-z0-9._:-]{8,96}")String eventId,
   @NotBlank @Pattern(regexp="SUPPLIER_MASTER|PO|PO_CHANGE_RESULT|RECEIPT|MES_PRIORITY|FIN_ACK|PAYMENT|QMS_INSPECTION|ERP_PERFORMANCE")String resource,
   @NotBlank @Size(max=96)String businessKey,@Min(1) @Max(9007199254740991L)long version,@Min(1)long occurredAt,
   @NotNull @Size(max=100)Map<String,Object> data){}
 public Map<String,Object> receive(Map<String,Object> connector,String raw){require(raw.getBytes(StandardCharsets.UTF_8).length<=1024*1024,400,"入站报文不能超过1MB");Ingress p;try{p=x.mapper.readValue(raw,Ingress.class);}catch(Exception e){throw new CommonException(400,"入站事件格式无效");}require(validator.validate(p).isEmpty(),400,"入站事件标识、版本或字段范围无效");
  String system=s(connector,"SYSTEM_KEY");Set<String> allowed=switch(system){case "ERP"->Set.of("SUPPLIER_MASTER","PO","PO_CHANGE_RESULT","RECEIPT","PAYMENT","ERP_PERFORMANCE");case "MES"->Set.of("MES_PRIORITY");case "FINANCE"->Set.of("FIN_ACK","PAYMENT");case "QMS"->Set.of("QMS_INSPECTION");default->Set.of();};require(allowed.contains(p.resource()),403,"连接系统不能提交此类业务事件");
  String hash=x.hash(p),dataHash=x.hash(Map.of("resource",p.resource(),"key",p.businessKey(),"version",p.version(),"data",p.data()));
  String id=x.tx(()->{var old=x.db.queryForList("SELECT ID,REQUEST_HASH FROM SRM_XCH_INBOX WHERE CONNECTOR_ID=? AND EVENT_KEY=?",connector.get("ID"),p.eventId());if(!old.isEmpty()){require(hash.equals(old.get(0).get("REQUEST_HASH")),409,"事件ID重复但内容不同");return s(old.get(0),"ID");}String next=id();try{x.db.update("INSERT INTO SRM_XCH_INBOX(ID,CONNECTOR_ID,EVENT_KEY,RESOURCE,BUSINESS_KEY,SOURCE_VERSION,REQUEST_HASH,DATA_HASH,PAYLOAD_CIPHER,STATUS,NEXT_RETRY_AT,CREATED_AT) VALUES(?,?,?,?,?,?,?,?,?,'RECEIVED',NOW(3),NOW(3))",next,connector.get("ID"),p.eventId(),p.resource(),p.businessKey(),p.version(),hash,dataHash,x.crypto.encrypt(x.json(p)));}catch(org.springframework.dao.DuplicateKeyException e){throw new CommonException(409,"事件已被并发接收，请用原事件和新nonce查询重试");}return next;});
  process(id);return receipt(id);
 }
 public Map<String,Object> receipt(String id){return x.db.queryForMap("SELECT ID AS id,EVENT_KEY AS eventId,RESOURCE AS resource,BUSINESS_KEY AS businessKey,SOURCE_VERSION AS version,STATUS AS status,ATTEMPTS AS attempts,LAST_ERROR AS lastError FROM SRM_XCH_INBOX WHERE ID=?",id);}
 void process(String id){try{x.tx(()->{
  var rows=x.db.queryForList("SELECT * FROM SRM_XCH_INBOX WHERE ID=? AND STATUS IN ('RECEIVED','RETRY','WAITING_VERSION','WAITING_DEPENDENCY') FOR UPDATE SKIP LOCKED",id);if(rows.isEmpty())return null;var row=rows.get(0);var connector=x.connector(s(row,"CONNECTOR_ID"));if(!Boolean.TRUE.equals(connector.get("ENABLED")))return null;
  Object[] stream={row.get("CONNECTOR_ID"),row.get("RESOURCE"),row.get("BUSINESS_KEY")};x.db.update("INSERT IGNORE INTO SRM_XCH_STREAM(CONNECTOR_ID,RESOURCE,BUSINESS_KEY,VERSION) VALUES(?,?,?,0)",stream);
  var current=x.db.queryForMap("SELECT VERSION FROM SRM_XCH_STREAM WHERE CONNECTOR_ID=? AND RESOURCE=? AND BUSINESS_KEY=? FOR UPDATE",stream);long version=n(row,"SOURCE_VERSION"),last=n(current,"VERSION");
  if(version<=last){var old=x.db.queryForList("SELECT DATA_HASH FROM SRM_XCH_JOURNAL WHERE CONNECTOR_ID=? AND RESOURCE=? AND BUSINESS_KEY=? AND VERSION=?",stream[0],stream[1],stream[2],version);require(old.size()==1&&old.get(0).get("DATA_HASH").equals(row.get("DATA_HASH")),409,"SOURCE_VERSION_CONFLICT");x.db.update("UPDATE SRM_XCH_INBOX SET STATUS='DUPLICATE',LAST_ERROR=NULL,APPLIED_AT=NOW(3) WHERE ID=?",id);return null;}
  if(version!=last+1){x.db.update("UPDATE SRM_XCH_INBOX SET STATUS='WAITING_VERSION',LAST_ERROR='MISSING_PREVIOUS_VERSION',NEXT_RETRY_AT=DATE_ADD(NOW(3),INTERVAL 5 SECOND) WHERE ID=?",id);return null;}
  Ingress p;try{p=x.mapper.readValue(x.crypto.decrypt(s(row,"PAYLOAD_CIPHER")),Ingress.class);}catch(Exception e){throw new CommonException(400,"STORED_EVENT_INVALID");}
  if(Set.of("QMS_INSPECTION","ERP_PERFORMANCE").contains(p.resource()))quality.apply(new vip.xiaonuo.srm.performance.api.SrmQualityIngressApi.Origin(s(connector,"ID"),s(connector,"ORG_ID"),s(connector,"SYSTEM_KEY"),s(connector,"MODE"),s(connector,"CREATED_BY")),p.resource(),p.businessKey(),p.version(),p.data());else business.apply(x.origin(connector),new Command(p.eventId(),p.resource(),p.businessKey(),p.version(),p.occurredAt(),p.data()));
  x.db.update("INSERT INTO SRM_XCH_JOURNAL(CONNECTOR_ID,RESOURCE,BUSINESS_KEY,VERSION,DATA_HASH,INBOX_ID,CREATED_AT) VALUES(?,?,?,?,?,?,NOW(3))",stream[0],stream[1],stream[2],version,row.get("DATA_HASH"),id);
  x.db.update("UPDATE SRM_XCH_STREAM SET VERSION=? WHERE CONNECTOR_ID=? AND RESOURCE=? AND BUSINESS_KEY=?",version,stream[0],stream[1],stream[2]);x.db.update("UPDATE SRM_XCH_INBOX SET STATUS='APPLIED',LAST_ERROR=NULL,APPLIED_AT=NOW(3),ATTEMPTS=ATTEMPTS+1 WHERE ID=?",id);
  x.db.update("UPDATE SRM_XCH_INBOX SET NEXT_RETRY_AT=NOW(3) WHERE CONNECTOR_ID=? AND RESOURCE=? AND BUSINESS_KEY=? AND SOURCE_VERSION=? AND STATUS IN ('WAITING_VERSION','WAITING_DEPENDENCY')",stream[0],stream[1],stream[2],version+1);return null;
 });}catch(Exception error){try{x.tx(()->{var rows=x.db.queryForList("SELECT ATTEMPTS,STATUS FROM SRM_XCH_INBOX WHERE ID=? FOR UPDATE",id);if(rows.isEmpty()||Set.of("APPLIED","DUPLICATE").contains(s(rows.get(0),"STATUS")))return null;int attempts=((Number)rows.get(0).get("ATTEMPTS")).intValue()+1;String status,reason;if(error instanceof PendingDependency){status="WAITING_DEPENDENCY";reason=error.getMessage();}else if(error instanceof CommonException e){status=e.getCode()==409?"CONFLICT":"FAILED";reason=e.getMsg();}else{status=attempts>=5?"FAILED":"RETRY";reason="PROCESSING_FAILED_RETRY";}x.db.update("UPDATE SRM_XCH_INBOX SET STATUS=?,ATTEMPTS=?,LAST_ERROR=?,NEXT_RETRY_AT=DATE_ADD(NOW(3),INTERVAL ? SECOND) WHERE ID=?",status,attempts,reason.substring(0,Math.min(160,reason.length())),Math.min(300,1<<Math.min(attempts,8)),id);return null;});}catch(Exception unavailable){/* Inbox remains persisted and the transaction was rolled back; next scheduler run retries it. */}}}
 @Scheduled(fixedDelay=1000) public void incoming(){try{for(String id:x.db.queryForList("SELECT ID FROM SRM_XCH_INBOX WHERE STATUS IN ('RECEIVED','RETRY','WAITING_VERSION','WAITING_DEPENDENCY') AND NEXT_RETRY_AT<=NOW(3) ORDER BY CREATED_AT,ID LIMIT 30",String.class))process(id);x.db.update("DELETE FROM SRM_XCH_NONCE WHERE EXPIRES_MS<?",System.currentTimeMillis());}catch(Exception unavailable){/* No event is acknowledged as applied while the database is unavailable. */}}
 @Scheduled(fixedDelay=1000) public void outgoing(){List<Map<String,Object>> batch;try{batch=x.tx(()->{var rows=x.db.queryForList("SELECT o.* FROM SRM_XCH_OUTBOX o JOIN SRM_XCH_CONNECTOR c ON c.ID=o.CONNECTOR_ID AND c.ENABLED=true WHERE (o.STATUS IN ('PENDING','RETRY') AND o.NEXT_RETRY_AT<=NOW(3)) OR (o.STATUS='INFLIGHT' AND o.LEASE_UNTIL<NOW(3)) ORDER BY o.CREATED_AT,o.ID LIMIT 5 FOR UPDATE SKIP LOCKED");for(var row:rows){String lease=UUID.randomUUID().toString();x.db.update("UPDATE SRM_XCH_OUTBOX SET STATUS='INFLIGHT',LEASE_ID=?,LEASE_UNTIL=DATE_ADD(NOW(3),INTERVAL 30 SECOND),ATTEMPTS=ATTEMPTS+1 WHERE ID=?",lease,row.get("ID"));row.put("LEASE_ID",lease);row.put("ATTEMPTS",((Number)row.get("ATTEMPTS")).intValue()+1);}return rows;});}catch(Exception unavailable){return;}
  for(var row:batch){boolean ok=false;String reason="REMOTE_REJECTED",reference=null;try{var c=x.connector(s(row,"CONNECTOR_ID"));var endpoint=x.endpoint(s(c,"SYSTEM_KEY"),s(c,"MODE"),s(c,"ENDPOINT"));String body=x.crypto.decrypt(s(row,"PAYLOAD_CIPHER")),ts=Long.toString(System.currentTimeMillis()),nonce=UUID.randomUUID().toString().replace("-","");var request=HttpRequest.newBuilder(endpoint).timeout(Duration.ofSeconds(4)).header("Content-Type","application/json").header("X-SRM-Connector",s(c,"ID")).header("X-SRM-Timestamp",ts).header("X-SRM-Nonce",nonce).header("X-SRM-Signature",signature(x.crypto.decrypt(s(c,"SECRET_CIPHER")),"POST",endpoint.getRawPath(),ts,nonce,body)).header("Idempotency-Key",s(row,"EVENT_KEY")).POST(HttpRequest.BodyPublishers.ofString(body)).build();var response=client.send(request,HttpResponse.BodyHandlers.ofInputStream());byte[] bytes;try(var input=response.body()){bytes=input.readNBytes(65537);}if(bytes.length<=65536&&response.statusCode()>=200&&response.statusCode()<300){var receipt=x.object(new String(bytes,StandardCharsets.UTF_8));ok=Boolean.TRUE.equals(receipt.get("accepted"))&&s(row,"EVENT_KEY").equals(receipt.get("eventId"));reference=String.valueOf(receipt.getOrDefault("receiptId",""));}else reason="REMOTE_HTTP_"+response.statusCode();}catch(Exception failure){reason="TRANSPORT_FAILED";if(failure instanceof InterruptedException)Thread.currentThread().interrupt();}
   final boolean delivered=ok;final String error=reason,ref=reference;try{x.tx(()->{int attempts=((Number)row.get("ATTEMPTS")).intValue();int delay=Math.min(3600,(s(row,"MODE").equals("LIVE")?30:2)*(1<<Math.min(attempts,6)));x.db.update("UPDATE SRM_XCH_OUTBOX SET STATUS=?,LAST_ERROR=?,REMOTE_REF=?,DELIVERED_AT=CASE WHEN ? THEN NOW(3) ELSE DELIVERED_AT END,NEXT_RETRY_AT=DATE_ADD(NOW(3),INTERVAL ? SECOND),LEASE_ID=NULL,LEASE_UNTIL=NULL WHERE ID=? AND LEASE_ID=? AND STATUS='INFLIGHT'",delivered?"DELIVERED":attempts>=5?"FAILED":"RETRY",delivered?null:error,ref==null?null:ref.substring(0,Math.min(128,ref.length())),delivered,delay,row.get("ID"),row.get("LEASE_ID"));return null;});}catch(Exception unavailable){/* Persisted lease expires; retry uses exactly the same remote event ID. */}
  }
 }
}
